import{_ as d,o as r,c as o,a2 as n}from"./chunks/framework.CvydjLy7.js";const p=JSON.parse('{"title":"9.1 四层测试：先划线，再动手写","description":"","frontmatter":{"title":"9.1 四层测试：先划线，再动手写"},"headers":[{"level":3,"title":"划线的两条问题","slug":"划线的两条问题","link":"#划线的两条问题","children":[]}],"relativePath":"ch09/01.md","filePath":"ch09/01.md","lastUpdated":1789497795000}'),s={name:"ch09/01.md"};function e(a,t,l,i,g,c){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="_9-1-四层测试-先划线-再动手写" tabindex="-1">9.1 四层测试：先划线，再动手写 <a class="header-anchor" href="#_9-1-四层测试-先划线-再动手写" aria-label="Permalink to &quot;9.1 四层测试：先划线，再动手写&quot;">​</a></h1><p>测试分层的意义不是“显得专业”，是<strong>省时间</strong>。下面这张表的耗时是实测值，同一个工程、同一台机器：</p><table tabindex="0"><thead><tr><th>层次</th><th>启动的东西</th><th>用例数</th><th>实测耗时</th><th>适合测什么</th></tr></thead><tbody><tr><td>纯单元测试</td><td>什么都不起</td><td>5</td><td><strong>0.68 s</strong></td><td>业务规则、分支、异常路径</td></tr><tr><td>Web 切片</td><td>只有 MVC 那半边容器</td><td>4</td><td><strong>0.31 s</strong></td><td>路由、入参校验、响应体格式、异常映射</td></tr><tr><td>数据访问切片</td><td>JPA + 内嵌数据库</td><td>5</td><td><strong>0.56 s</strong></td><td>仓储方法名解析出的 SQL 行为</td></tr><tr><td>整体测试（Mock 环境）</td><td>完整容器，不起服务器</td><td>4</td><td><strong>2.43 s</strong></td><td>一次请求穿透所有层，但不走网络</td></tr><tr><td>整体测试（真实端口）</td><td>完整容器 + 内嵌 Tomcat</td><td>3</td><td><strong>0.66 s</strong></td><td>序列化、HTTP 状态码、真实网络栈</td></tr><tr><td>条件装配</td><td>极小的手工上下文</td><td>4</td><td><strong>0.02 s</strong></td><td>开关、<code>@ConditionalOn*</code> 是否按预期生效</td></tr><tr><td>测试工具</td><td>什么都不起</td><td>2</td><td><strong>0.01 s</strong></td><td>输出捕获、临时属性注入</td></tr><tr><td>Testcontainers</td><td>完整容器 + 真实 MySQL</td><td>4</td><td><strong>9.28 s</strong></td><td>方言、字符集、真实约束行为</td></tr></tbody></table><p>几个从这张表里能直接读出来的结论：</p><ol><li><strong>纯单元测试比 Web 切片快一倍，Web 切片比整体测试快一个数量级。</strong> 一个断言逻辑分支的测试如果写在 <code>@SpringBootTest</code> 里，你付出的代价是它的几百倍，换来的可信度却完全一样。</li><li><strong>“真实端口”没有比“Mock 环境”慢很多</strong>。这一点常被误解——2.43 s 那个数字看着更大，是因为它包含了整个容器首次启动的开销（数据库初始化、JPA 元模型构建），后面几个整体测试类复用了同一个上下文，所以轮到真实端口那个类时只剩 0.66 s。稳定跑起来之后，两者的差距主要在 Tomcat 启动和 TCP 往返上，通常几十毫秒量级。</li><li><strong>条件装配那一层的成本几乎为零。</strong> 用 <code>ApplicationContextRunner</code> 搭一个只装两三个类的小上下文，4 个用例 17 毫秒。需要验证“开关打开时有没有这个 Bean”，不该去启动整个应用。</li><li><strong>Testcontainers 一层比其余所有层加起来还贵。</strong> 9.28 s 里绝大部分是容器启动与 MySQL 初始化，跟用例写了几个关系不大。所以它的定位是<strong>补充</strong>而不是<strong>替代</strong>：日常迭代跑前面几层，涉及方言与字符集的用例放到这一层，在 CI 上完整跑。</li></ol><h3 id="划线的两条问题" tabindex="-1">划线的两条问题 <a class="header-anchor" href="#划线的两条问题" aria-label="Permalink to &quot;划线的两条问题&quot;">​</a></h3><p>每写一个测试前，问两句话就够：</p><ul><li><strong>被测的这段逻辑里，有没有 Spring 特有的行为？</strong>（事务代理、条件装配、AOP、参数解析）——没有的话，别起容器。</li><li><strong>有没有真实的外部依赖？</strong>（数据库、HTTP、消息队列）——没有的话，用假对象就够，别连真的。</li></ul><p>两个问题都是“否”，写在最底层。任一为“是”，往上走一层，并且<strong>只走必要的那些层</strong>。</p><hr>',10)])])}const _=d(s,[["render",e]]);export{p as __pageData,_ as default};
